entries[97989] = { ["name"] = "Verzauberter Feendrache", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren verzauberten Feendrachen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese majestätische Kreatur ist Wolkenglanzes älterer Bruder. Er versichert, dass sie eigentlich adoptiert wurde.\"\nWoW-Shop" }
