entries[98104] = { ["name"] = "Gepanzerter roter Drachenfalke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren gepanzerten roten Drachenfalken oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese seltene Art von Drachenfalken ist ein Ehrenzeichen in der Horde, das von den Blutelfen gewährt wurde. Es spiegelt Euer endloses Streben wieder, eine kleine Armee von Reittieren anzusammeln.\"\nErfolg:\nReittieraufmarsch\nKategorie:\nAllgemein" }
entries[98111] = { ["name"] = "5-Minuten-Kodo", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 4340 Gesundheit und ( 1118 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, erleidet Ihr 1 Stunde lang weniger Schaden, während Ihr Euch im Nördlichen Brachland aufhaltet.\n\"Nur heißes Wasser hinzufügen.\"\nVerkaufspreis:" }
entries[98112] = { ["name"] = "Kleines Leckerli", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhöht die durch Haustierkämpfe gewonnene Erfahrung 1 Stunde lang um 25%.\n\"Aus echtem Eberfleisch!\"\nVerkaufspreis:" }
entries[98113] = { ["name"] = "Stapel Briefe", ["text"] = "Wird beim Aufheben gebunden\n\"Briefe einer geliebten Person, in grober Orcschrift verfasst.\"\nVerkaufspreis:" }
entries[98114] = { ["name"] = "Leckerli", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhöht die durch Haustierkämpfe gewonnene Erfahrung 1 Stunde lang um 50%.\n\"Doppelt so viele Zutaten wie Konkurrenzprodukte!\"\nVerkaufspreis:" }
entries[98115] = { ["name"] = "Trophäenhalskette", ["text"] = "Wird beim Aufheben gebunden\n\"Die meisten Hauer scheinen von Stachelebern oder Kodos zu stammen. Manche der frischen nicht.\"\nVerkaufspreis:" }
entries[98116] = { ["name"] = "Gefriergetrocknetes Hyänenfleisch", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 4340 Gesundheit und ( 1118 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, bewegt Ihr Euch 1 Stunde lang schneller, während Ihr Euch im Nördlichen Brachland aufhaltet.\nVerkaufspreis:" }
entries[98117] = { ["name"] = "Geldbräu", ["text"] = "Einzigartig (24)\nBenutzen: Nehmt einen kräftigen Schluck von der goldenen Erfrischung. Das ist ein alkoholfreies Getränk. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[98118] = { ["name"] = "Knusperskorpione", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 4340 Gesundheit und ( 1118 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, verursacht Ihr 1 Stunde lang mehr Schaden, während Ihr Euch im Nördlichen Brachland aufhaltet.\nVerkaufspreis:" }
entries[98119] = { ["name"] = "Unlesbare Pläne", ["text"] = "Wird beim Aufheben gebunden\n\"Diesen wirren Kritzeleien kann man nur mit Mühe und Not entnehmen, dass es dabei irgendwie um eine Ausgrabung geht.\"\nVerkaufspreis:" }
entries[98120] = { ["name"] = "Lieferschein", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Beleg für eine große Anzahl versiegelte Behälter, die nach Orgrimmar geliefert wurden.\"\nVerkaufspreis:" }
entries[98121] = { ["name"] = "Bernsteinsamenbrötchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft das Bernsteinsamenbrötchen.\n\"Aus irgendeinem Grund war es dieses Jahr schwierig, an frische Bernsteinsamen zu kommen.\"\nVerkaufspreis:" }
entries[98122] = { ["name"] = "Camembert du Grollhouffe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Tempo.\n\"Wie man vorhersagen könnte, ist es außerordentlich schwierig, einen Grollhuf zu melken.\"\nVerkaufspreis:" }
entries[98123] = { ["name"] = "Walhaikaviar", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 kritischen Trefferwert.\n\"Hat einen sehr salzigen Geschmack, ähnlich wie Tränen.\"\nVerkaufspreis:" }
entries[98124] = { ["name"] = "Blutbeerenkuchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Parieren.\n\"Blutbeeren sind eigentlich ziemlich verbreitet, nur geht heute fast keiner mehr nach Quel'Danas, um sie zu pflücken.\"\nVerkaufspreis:" }
entries[98125] = { ["name"] = "Gehobelte Zangartrüffeln", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Ausweichen.\n\"Nur ein sehr kleiner Teil der Zangartrüffel ist nicht giftig. Es ist dieser Teil.\"\nVerkaufspreis:" }
entries[98126] = { ["name"] = "Foie gras de poulet mécanique", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 kritischen Trefferwert.\n\"Wir garantieren, dass dieser Robopieps human behandelt und nicht zwangsgeölt wurde.\"\nVerkaufspreis:" }
entries[98127] = { ["name"] = "Verbeulte Büchse Kaja'Cola", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 20 Sek. 21682 Gesundheit und ( 5000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang 10 Meisterschaft.\n\"Sehr schwer aufzutreiben. Es gibt davon nur noch wenige.\"\nVerkaufspreis:" }
