entries[98405] = { ["name"] = "Kräftiges Mushan des Grubenkämpfers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares kräftiges Mushan des Grubenkämpfers und gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Jahrelang glaubten Pandaren, dass diese Kreaturen nicht gezähmt werden könnten. Fragt einfach Henshi \"Hinkebein\" Heimbräu, den ersten Pandaren, der es geschafft hat.\"\nVerkäufer:\nPaul Norden\nZone:\nShlae'gararena\nKosten:" }
